 package hotel.reservations;

 import hotel.rooms.Room;
+import hotel.rooms.RoomType;
 import java.math.BigDecimal;
 import java.math.RoundingMode;
+import java.time.DayOfWeek;
 import java.time.LocalDate;
 import java.time.Month;

@@ -15,19 +17,88 @@ public final class PriceCalculator {

     static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
     static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
+    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");

-    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
+    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
+        int nights = countNights(checkIn, checkOut);
+        return switch (ratePlan) {
+            case STANDARD -> calculateStandard(room, checkIn, checkOut, nights);
+            case NON_REFUNDABLE -> calculateNonRefundable(room, checkIn, checkOut, nights);
+            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, nights, companyCode);
+            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut, nights);
+            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut, nights);
+        };
+    }
+
+    private Price calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
+        BigDecimal subtotal = sumNights(room, checkIn, checkOut);
+        BigDecimal discount = cents(BigDecimal.ZERO);
+        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
+    }
+
+    private Price calculateNonRefundable(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
+        BigDecimal subtotal = sumNights(room, checkIn, checkOut);
+        BigDecimal discount = cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
+        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
+    }
+
+    private Price calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
+        if (companyCode == null || companyCode.isBlank()) {
+            throw new HotelException(ErrorCode.INVALID_REQUEST, "corporate rate plan requires a company code");
+        }
+        BigDecimal discountRate = switch (companyCode.toUpperCase()) {
+            case "TECNOSUL" -> new BigDecimal("0.12");
+            case "AGROVALE" -> new BigDecimal("0.18");
+            case "FARMAVIDA" -> new BigDecimal("0.25");
+            default -> throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "company code '" + companyCode + "' is not recognized");
+        };
+        BigDecimal subtotal = sumNights(room, checkIn, checkOut);
+        BigDecimal discount = cents(subtotal.multiply(discountRate));
+        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
+    }
+
+    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
+        if (nights != 2) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "weekend package requires exactly 2 nights");
+        }
+        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY || checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "weekend package must be friday check-in and sunday check-out");
+        }
+        BigDecimal packagePrice = switch (room.type()) {
+            case STANDARD -> new BigDecimal("520.00");
+            case DELUXE -> new BigDecimal("820.00");
+            case SUITE -> new BigDecimal("1200.00");
+        };
+        return new Price(nights, packagePrice, cents(BigDecimal.ZERO), packagePrice);
+    }
+
+    private Price calculateLongStay(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
+        if (nights < 7) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "long stay rate plan requires at least 7 nights");
+        }
+        BigDecimal subtotal = sumNights(room, checkIn, checkOut);
+        BigDecimal discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
+        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
+    }
+
+    private int countNights(LocalDate checkIn, LocalDate checkOut) {
         int nights = 0;
-        BigDecimal subtotal = cents(BigDecimal.ZERO);
         for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
-            subtotal = subtotal.add(nightPrice(room, night));
             nights++;
         }
-        BigDecimal discount = switch (ratePlan) {
-            case STANDARD -> cents(BigDecimal.ZERO);
-            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
-        };
-        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
+        return nights;
+    }
+
+    private BigDecimal sumNights(Room room, LocalDate checkIn, LocalDate checkOut) {
+        BigDecimal sum = cents(BigDecimal.ZERO);
+        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
+            sum = sum.add(nightPrice(room, night));
+        }
+        return sum;
     }

     BigDecimal nightPrice(Room room, LocalDate night) {
