     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import hotel.rooms.RoomType;
     5	import java.math.BigDecimal;
     6	import java.math.RoundingMode;
     7	import java.time.DayOfWeek;
     8	import java.time.LocalDate;
     9	import java.time.Month;
    10	
    11	/**
    12	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    13	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    14	 * (half-even) at every step.
    15	 */
    16	public final class PriceCalculator {
    17	
    18	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    19	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    20	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
    21	
    22	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    23	        int nights = countNights(checkIn, checkOut);
    24	        return switch (ratePlan) {
    25	            case STANDARD -> calculateStandard(room, checkIn, checkOut, nights);
    26	            case NON_REFUNDABLE -> calculateNonRefundable(room, checkIn, checkOut, nights);
    27	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, nights, companyCode);
    28	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut, nights);
    29	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut, nights);
    30	        };
    31	    }
    32	
    33	    private Price calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    34	        BigDecimal subtotal = sumNights(room, checkIn, checkOut);
    35	        BigDecimal discount = cents(BigDecimal.ZERO);
    36	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    37	    }
    38	
    39	    private Price calculateNonRefundable(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    40	        BigDecimal subtotal = sumNights(room, checkIn, checkOut);
    41	        BigDecimal discount = cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    42	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    43	    }
    44	
